package com.cuatest.touchtest;

import android.app.Activity;
import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.IntentFilter;
import android.os.Build;
import android.os.Bundle;
import android.util.Log;
import android.view.Window;
import android.view.WindowManager;

/**
 * Single-activity host for {@link TouchView}.
 *
 * <p>Registers a {@link BroadcastReceiver} for the action
 * {@code com.cuatest.touchtest.RESET_LOG} so the test harness can atomically
 * clear the in-memory sequence counter between test cases:
 * <pre>
 *   adb shell am broadcast -a com.cuatest.touchtest.RESET_LOG
 * </pre>
 */
public class MainActivity extends Activity {

    private static final String TAG = "TouchTest";
    private TouchView mTouchView;

    private final BroadcastReceiver mResetReceiver = new BroadcastReceiver() {
        @Override
        public void onReceive(Context ctx, Intent intent) {
            if ("com.cuatest.touchtest.RESET_LOG".equals(intent.getAction())) {
                Log.d(TAG, "{\"type\":\"BROADCAST\",\"msg\":\"RESET_LOG received\"}");
                if (mTouchView != null) {
                    mTouchView.resetLog();
                }
            }
        }
    };

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // Fullscreen, keep screen on
        requestWindowFeature(Window.FEATURE_NO_TITLE);
        getWindow().setFlags(
                WindowManager.LayoutParams.FLAG_FULLSCREEN |
                WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON,
                WindowManager.LayoutParams.FLAG_FULLSCREEN |
                WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON
        );

        mTouchView = new TouchView(this);
        setContentView(mTouchView);

        // Log device capabilities
        Log.d(TAG, "{\"type\":\"DEVICE_INFO\","
                + "\"model\":\"" + Build.MODEL + "\","
                + "\"sdk\":" + Build.VERSION.SDK_INT + ","
                + "\"multitouch_distinct\":"
                + getPackageManager().hasSystemFeature("android.hardware.touchscreen.multitouch.distinct")
                + "}");
    }

    @Override
    protected void onResume() {
        super.onResume();
        IntentFilter filter = new IntentFilter("com.cuatest.touchtest.RESET_LOG");
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            registerReceiver(mResetReceiver, filter, Context.RECEIVER_NOT_EXPORTED);
        } else {
            registerReceiver(mResetReceiver, filter);
        }
        Log.d(TAG, "{\"type\":\"LIFECYCLE\",\"msg\":\"onResume — app is active\"}");
    }

    @Override
    protected void onPause() {
        super.onPause();
        try { unregisterReceiver(mResetReceiver); } catch (IllegalArgumentException ignored) {}
        Log.d(TAG, "{\"type\":\"LIFECYCLE\",\"msg\":\"onPause\"}");
    }
}

package com.cuatest.touchtest;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.util.Log;
import android.view.MotionEvent;
import android.view.View;

import java.util.ArrayList;
import java.util.List;

/**
 * Full-screen view that:
 * <ul>
 *   <li>Intercepts every {@link MotionEvent} (including multi-touch).</li>
 *   <li>Logs each event as a JSON line to Logcat under tag {@code TouchTest}.</li>
 *   <li>Draws live touch indicators on a black canvas for visual debugging.</li>
 * </ul>
 *
 * <h3>Reading results</h3>
 * <pre>
 *   adb logcat -s TouchTest -d
 * </pre>
 * Each line has the form:
 * <pre>
 *   D TouchTest: {"seq":1,"action":"ACTION_DOWN","pointer_count":1,...}
 * </pre>
 *
 * <h3>Resetting the log</h3>
 * Clear Logcat before each test so results are unambiguous:
 * <pre>
 *   adb logcat -c
 * </pre>
 */
public class TouchView extends View {

    public static final String LOG_TAG = "TouchTest";

    // Marker emitted once the view is ready; the test harness waits for this.
    public static final String READY_MARKER = "{\"type\":\"READY\",\"msg\":\"TouchView is accepting events\"}";
    // Marker emitted after a RESET_LOG broadcast is handled.
    public static final String RESET_MARKER = "{\"type\":\"RESET\",\"msg\":\"event log cleared\"}";

    private final Paint mCirclePaint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint mLabelPaint  = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint mInfoPaint   = new Paint(Paint.ANTI_ALIAS_FLAG);

    // Snapshot of active pointers for rendering
    private final List<float[]> mActivePointers = new ArrayList<>();
    private String mLastAction = "—";
    private int mLastPointerCount = 0;

    public TouchView(Context context) {
        super(context);

        mCirclePaint.setColor(Color.parseColor("#4FC3F7"));
        mCirclePaint.setStyle(Paint.Style.FILL);
        mCirclePaint.setAlpha(200);

        mLabelPaint.setColor(Color.WHITE);
        mLabelPaint.setTextSize(32f);
        mLabelPaint.setTextAlign(Paint.Align.CENTER);

        mInfoPaint.setColor(Color.parseColor("#B0BEC5"));
        mInfoPaint.setTextSize(40f);

        // Signal that the view is ready
        Log.d(LOG_TAG, READY_MARKER);
    }

    /** Called by MainActivity when it receives the RESET_LOG broadcast. */
    public void resetLog() {
        TouchEvent.resetSequence();
        mActivePointers.clear();
        mLastAction = "—";
        mLastPointerCount = 0;
        invalidate();
        Log.d(LOG_TAG, RESET_MARKER);
    }

    @Override
    public boolean onTouchEvent(MotionEvent ev) {
        // Capture and log the event
        TouchEvent te = TouchEvent.from(ev);
        Log.d(LOG_TAG, te.toJson());

        // Update render state
        mLastAction = te.action;
        mLastPointerCount = te.pointerCount;
        mActivePointers.clear();
        if (ev.getActionMasked() != MotionEvent.ACTION_UP &&
                ev.getActionMasked() != MotionEvent.ACTION_CANCEL) {
            for (int i = 0; i < ev.getPointerCount(); i++) {
                mActivePointers.add(new float[]{ev.getX(i), ev.getY(i)});
            }
        }
        invalidate();
        return true;  // consume all events
    }

    @Override
    protected void onDraw(Canvas canvas) {
        canvas.drawColor(Color.BLACK);

        // Draw touch circles
        for (int i = 0; i < mActivePointers.size(); i++) {
            float[] p = mActivePointers.get(i);
            canvas.drawCircle(p[0], p[1], 80f, mCirclePaint);
            canvas.drawText(String.valueOf(i), p[0], p[1] + 12f, mLabelPaint);
        }

        // HUD
        float margin = 60f;
        canvas.drawText("Action : " + mLastAction,          margin, 120f,  mInfoPaint);
        canvas.drawText("Pointers: " + mLastPointerCount,   margin, 180f,  mInfoPaint);
        canvas.drawText("Active  : " + mActivePointers.size(), margin, 240f, mInfoPaint);

        // Centre prompt when idle
        if (mActivePointers.isEmpty()) {
            Paint p = new Paint(mInfoPaint);
            p.setTextAlign(Paint.Align.CENTER);
            p.setColor(Color.parseColor("#546E7A"));
            canvas.drawText("Touch here to test", getWidth() / 2f, getHeight() / 2f, p);
        }
    }
}

package com.cuatest.touchtest;

import android.view.MotionEvent;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

/**
 * Lightweight, serialisable representation of a single MotionEvent sample.
 *
 * <p>Written to Logcat with tag {@code TouchTest} so that the test harness can
 * read results via {@code adb logcat -s TouchTest -d} without requiring any
 * file-system permissions.
 */
public class TouchEvent {

    public final String action;
    public final int pointerCount;
    public final int[] ids;
    public final float[] xs;
    public final float[] ys;
    public final float[] pressures;
    public final long eventTimeMs;
    public final long sequenceId;   // monotonically increasing across the session

    private static long sSequence = 0;

    private TouchEvent(String action, int pointerCount,
                       int[] ids, float[] xs, float[] ys, float[] pressures,
                       long eventTimeMs) {
        this.action = action;
        this.pointerCount = pointerCount;
        this.ids = ids;
        this.xs = xs;
        this.ys = ys;
        this.pressures = pressures;
        this.eventTimeMs = eventTimeMs;
        this.sequenceId = ++sSequence;
    }

    /** Reset the per-session sequence counter (called when the app receives RESET_LOG). */
    public static void resetSequence() {
        sSequence = 0;
    }

    /**
     * Converts a raw {@link MotionEvent} into a {@link TouchEvent}.
     *
     * <p>All active pointers are captured, regardless of which pointer triggered
     * the action.
     */
    public static TouchEvent from(MotionEvent ev) {
        int maskedAction = ev.getActionMasked();
        String actionName;
        switch (maskedAction) {
            case MotionEvent.ACTION_DOWN:           actionName = "ACTION_DOWN";          break;
            case MotionEvent.ACTION_UP:             actionName = "ACTION_UP";            break;
            case MotionEvent.ACTION_MOVE:           actionName = "ACTION_MOVE";          break;
            case MotionEvent.ACTION_CANCEL:         actionName = "ACTION_CANCEL";        break;
            case MotionEvent.ACTION_POINTER_DOWN:   actionName = "ACTION_POINTER_DOWN";  break;
            case MotionEvent.ACTION_POINTER_UP:     actionName = "ACTION_POINTER_UP";    break;
            case MotionEvent.ACTION_OUTSIDE:        actionName = "ACTION_OUTSIDE";       break;
            default:                               actionName = "ACTION_" + maskedAction; break;
        }

        int count = ev.getPointerCount();
        int[] ids        = new int[count];
        float[] xs       = new float[count];
        float[] ys       = new float[count];
        float[] pressures = new float[count];

        for (int i = 0; i < count; i++) {
            ids[i]        = ev.getPointerId(i);
            xs[i]         = ev.getX(i);
            ys[i]         = ev.getY(i);
            pressures[i]  = ev.getPressure(i);
        }

        return new TouchEvent(actionName, count, ids, xs, ys, pressures, ev.getEventTime());
    }

    /** Serialise to a compact JSON string (one line, no pretty-printing). */
    public String toJson() {
        try {
            JSONObject obj = new JSONObject();
            obj.put("seq", sequenceId);
            obj.put("action", action);
            obj.put("pointer_count", pointerCount);
            obj.put("event_time_ms", eventTimeMs);

            JSONArray pointers = new JSONArray();
            for (int i = 0; i < pointerCount; i++) {
                JSONObject p = new JSONObject();
                p.put("id", ids[i]);
                p.put("x", Math.round(xs[i]));
                p.put("y", Math.round(ys[i]));
                p.put("pressure", (float) Math.round(pressures[i] * 100) / 100f);
                pointers.put(p);
            }
            obj.put("pointers", pointers);
            return obj.toString();
        } catch (JSONException e) {
            return "{\"error\":\"json_serialisation_failed\"}";
        }
    }
}
